class CreatorMetricSnapshot { const CreatorMetricSnapshot({required this.views,required this.likes,required this.comments,required this.shares,required this.followersGained}); final int views,likes,comments,shares,followersGained; }
class CreatorAnalyticsSummary { const CreatorAnalyticsSummary(this.views,this.engagements,this.followersGained,this.engagementRate); final int views,engagements,followersGained; final double engagementRate; }
class CreatorAnalyticsAggregator { const CreatorAnalyticsAggregator(); CreatorAnalyticsSummary aggregate(Iterable<CreatorMetricSnapshot> items) { var v=0,l=0,c=0,s=0,f=0; for(final x in items){v+=_safe(x.views);l+=_safe(x.likes);c+=_safe(x.comments);s+=_safe(x.shares);f+=_safe(x.followersGained);} final e=l+c+s; return CreatorAnalyticsSummary(v,e,f,v==0?0:e/v); } int _safe(int n)=>n<0?0:n; }
